// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./VeilSBT.sol";

contract CreditOracle is Ownable {
    VeilSBT public immutable veilSBT;

    event CreditVerified(
        address indexed borrower,
        uint256 upiScore,
        uint256 gstScore,
        uint256 rentalScore,
        uint256 weightedScore,
        string tier,
        bytes32 proofHash,
        uint256 tokenId
    );

    error InvalidScore();
    error ScoreBelowMinimumTier();

    constructor(address veilSBTAddress) Ownable(msg.sender) {
        veilSBT = VeilSBT(veilSBTAddress);
    }

    function verifyCredit(
        address borrower,
        uint256 upiScore,
        uint256 gstScore,
        uint256 rentalScore
    ) external onlyOwner returns (uint256 tokenId, bytes32 proofHash) {
        if (upiScore > 100 || gstScore > 100 || rentalScore > 100) revert InvalidScore();

        uint256 weightedScore = (upiScore * 40) + (gstScore * 35) + (rentalScore * 25);
        string memory tier = _tierForScore(weightedScore);

        proofHash = keccak256(
            abi.encodePacked(
                borrower,
                upiScore,
                gstScore,
                rentalScore,
                weightedScore,
                block.timestamp,
                block.chainid
            )
        );

        tokenId = veilSBT.mint(borrower, tier, weightedScore, proofHash);

        emit CreditVerified(
            borrower,
            upiScore,
            gstScore,
            rentalScore,
            weightedScore,
            tier,
            proofHash,
            tokenId
        );
    }

    function tierForScore(uint256 score) external pure returns (string memory) {
        return _tierForScore(score);
    }

    function _tierForScore(uint256 score) internal pure returns (string memory) {
        if (score >= 8000 && score <= 10000) return "Platinum";
        if (score >= 6500 && score <= 7999) return "Gold";
        if (score >= 5000 && score <= 6499) return "Silver";
        if (score >= 3500 && score <= 4999) return "Bronze";
        revert ScoreBelowMinimumTier();
    }
}

