// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./ReputationEngine.sol";
import "./VeilSBT.sol";

contract LoanMarketplace is Ownable, ReentrancyGuard {
    enum LoanStatus {
        Listed,
        Disbursed,
        Repaid,
        Defaulted
    }

    struct Loan {
        uint256 id;
        address borrower;
        uint256 amount;
        string purpose;
        uint256 durationMonths;
        uint256 aprBps;
        string story;
        uint256 totalFunded;
        uint256 totalRepaid;
        uint256 totalRepayable;
        uint256 emiAmount;
        uint256 disbursedAt;
        uint256 emiPaidCount;
        LoanStatus status;
    }

    VeilSBT public immutable veilSBT;
    ReputationEngine public immutable reputationEngine;

    uint256 public nextLoanId = 1;
    uint256 public constant BPS_DENOMINATOR = 10_000;
    uint256 public constant MONTH = 30 days;
    uint256 public constant DEFAULT_GRACE_PERIOD = 60 days;

    mapping(uint256 => Loan) public loans;
    mapping(uint256 => address[]) private _loanLenders;
    mapping(uint256 => mapping(address => uint256)) public fundedAmount;
    mapping(uint256 => mapping(address => bool)) private _hasFunded;
    mapping(uint256 => mapping(uint256 => bool)) public emiPaid;

    event LoanListed(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 amount,
        string purpose,
        uint256 durationMonths,
        uint256 aprBps,
        string story
    );
    event Funded(uint256 indexed loanId, address indexed lender, uint256 amount, uint256 totalFunded);
    event Disbursed(uint256 indexed loanId, address indexed borrower, uint256 amount);
    event EMIPaid(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 emiIndex,
        uint256 amount,
        bool late
    );
    event LoanRepaid(uint256 indexed loanId, address indexed borrower, uint256 amount);
    event LoanDefaulted(uint256 indexed loanId, address indexed borrower);

    error NotSBTHolder();
    error InvalidLoan();
    error InvalidFunding();
    error LoanUnavailable();
    error NotBorrower();
    error NotDisbursed();
    error NothingDue();
    error DefaultUnavailable();
    error TransferFailed();

    constructor(address veilSBTAddress, address reputationEngineAddress) Ownable(msg.sender) {
        veilSBT = VeilSBT(veilSBTAddress);
        reputationEngine = ReputationEngine(reputationEngineAddress);
    }

    function listLoan(
        uint256 amount,
        string calldata purpose,
        uint256 durationMonths,
        uint256 aprBps,
        string calldata story
    ) external returns (uint256 loanId) {
        if (veilSBT.balanceOf(msg.sender) == 0) revert NotSBTHolder();
        if (amount == 0 || durationMonths == 0 || aprBps == 0) revert InvalidLoan();

        loanId = nextLoanId++;
        loans[loanId] = Loan({
            id: loanId,
            borrower: msg.sender,
            amount: amount,
            purpose: purpose,
            durationMonths: durationMonths,
            aprBps: aprBps,
            story: story,
            totalFunded: 0,
            totalRepaid: 0,
            totalRepayable: 0,
            emiAmount: 0,
            disbursedAt: 0,
            emiPaidCount: 0,
            status: LoanStatus.Listed
        });

        emit LoanListed(loanId, msg.sender, amount, purpose, durationMonths, aprBps, story);
    }

    function fund(uint256 loanId) external payable nonReentrant {
        Loan storage loan = loans[loanId];
        if (loan.status != LoanStatus.Listed) revert LoanUnavailable();
        if (msg.value == 0) revert InvalidFunding();

        uint256 remaining = loan.amount - loan.totalFunded;
        uint256 accepted = msg.value > remaining ? remaining : msg.value;
        uint256 refund = msg.value - accepted;

        if (!_hasFunded[loanId][msg.sender]) {
            _hasFunded[loanId][msg.sender] = true;
            _loanLenders[loanId].push(msg.sender);
        }

        fundedAmount[loanId][msg.sender] += accepted;
        loan.totalFunded += accepted;

        emit Funded(loanId, msg.sender, accepted, loan.totalFunded);

        if (loan.totalFunded == loan.amount) {
            _disburse(loanId, loan);
        }

        if (refund > 0) {
            _sendValue(msg.sender, refund);
        }
    }

    function repay(uint256 loanId) external payable nonReentrant {
        Loan storage loan = loans[loanId];
        if (msg.sender != loan.borrower) revert NotBorrower();
        if (loan.status != LoanStatus.Disbursed) revert NotDisbursed();

        uint256 outstanding = loan.totalRepayable - loan.totalRepaid;
        if (outstanding == 0) revert NothingDue();

        bool fullRepay = msg.value >= outstanding;
        uint256 amountToPay = fullRepay ? outstanding : nextEMIAmount(loanId);
        if (msg.value < amountToPay) revert NothingDue();

        uint256 previousPaidCount = loan.emiPaidCount;
        uint256 paidCountIncrement = fullRepay
            ? loan.durationMonths - loan.emiPaidCount
            : 1;

        for (uint256 i = 0; i < paidCountIncrement; i++) {
            emiPaid[loanId][loan.emiPaidCount + i + 1] = true;
        }

        loan.emiPaidCount += paidCountIncrement;
        loan.totalRepaid += amountToPay;

        bool late = block.timestamp > emiDueDate(loanId, previousPaidCount + 1);

        if (late) {
            reputationEngine.recordLatePayment(loan.borrower);
        } else {
            reputationEngine.recordOnTimeEMI(loan.borrower);
        }

        if (fullRepay && previousPaidCount + 1 < loan.durationMonths) {
            reputationEngine.recordEarlyRepay(loan.borrower);
        }

        _splitToLenders(loanId, amountToPay);

        emit EMIPaid(loanId, loan.borrower, previousPaidCount + 1, amountToPay, late);

        if (loan.totalRepaid >= loan.totalRepayable) {
            loan.status = LoanStatus.Repaid;
            reputationEngine.recordLoanComplete(loan.borrower);
            emit LoanRepaid(loanId, loan.borrower, loan.totalRepaid);
        }

        uint256 refund = msg.value - amountToPay;
        if (refund > 0) {
            _sendValue(msg.sender, refund);
        }
    }

    function markDefault(uint256 loanId) external {
        Loan storage loan = loans[loanId];
        if (loan.status != LoanStatus.Disbursed) revert DefaultUnavailable();
        if (block.timestamp <= emiDueDate(loanId, loan.emiPaidCount + 1) + DEFAULT_GRACE_PERIOD) {
            revert DefaultUnavailable();
        }

        loan.status = LoanStatus.Defaulted;
        reputationEngine.recordDefault(loan.borrower);

        emit LoanDefaulted(loanId, loan.borrower);
    }

    function lenders(uint256 loanId) external view returns (address[] memory) {
        return _loanLenders[loanId];
    }

    function getEMISchedule(
        uint256 loanId
    )
        external
        view
        returns (
            uint256[] memory dueDates,
            uint256[] memory amounts,
            bool[] memory paid
        )
    {
        Loan storage loan = loans[loanId];
        dueDates = new uint256[](loan.durationMonths);
        amounts = new uint256[](loan.durationMonths);
        paid = new bool[](loan.durationMonths);

        for (uint256 i = 0; i < loan.durationMonths; i++) {
            dueDates[i] = loan.disbursedAt == 0 ? 0 : loan.disbursedAt + ((i + 1) * MONTH);
            amounts[i] = _emiAmountForIndex(loan, i + 1);
            paid[i] = emiPaid[loanId][i + 1];
        }
    }

    function emiDueDate(uint256 loanId, uint256 emiIndex) public view returns (uint256) {
        Loan storage loan = loans[loanId];
        if (loan.disbursedAt == 0 || emiIndex == 0 || emiIndex > loan.durationMonths) return 0;
        return loan.disbursedAt + (emiIndex * MONTH);
    }

    function nextEMIAmount(uint256 loanId) public view returns (uint256) {
        Loan storage loan = loans[loanId];
        if (loan.emiPaidCount >= loan.durationMonths) return 0;
        return _emiAmountForIndex(loan, loan.emiPaidCount + 1);
    }

    function _disburse(uint256 loanId, Loan storage loan) internal {
        loan.status = LoanStatus.Disbursed;
        loan.disbursedAt = block.timestamp;
        loan.totalRepayable = _totalRepayable(loan.amount, loan.aprBps, loan.durationMonths);
        loan.emiAmount = _ceilDiv(loan.totalRepayable, loan.durationMonths);

        _sendValue(loan.borrower, loan.amount);
        emit Disbursed(loanId, loan.borrower, loan.amount);
    }

    function _splitToLenders(uint256 loanId, uint256 amount) internal {
        address[] memory loanLenders = _loanLenders[loanId];
        uint256 distributed = 0;

        for (uint256 i = 0; i < loanLenders.length; i++) {
            address lender = loanLenders[i];
            uint256 share;

            if (i == loanLenders.length - 1) {
                share = amount - distributed;
            } else {
                share = (amount * fundedAmount[loanId][lender]) / loans[loanId].amount;
                distributed += share;
            }

            if (share > 0) {
                _sendValue(lender, share);
            }
        }
    }

    function _emiAmountForIndex(Loan storage loan, uint256 emiIndex) internal view returns (uint256) {
        if (emiIndex == loan.durationMonths) {
            return loan.totalRepayable - (loan.emiAmount * (loan.durationMonths - 1));
        }
        return loan.emiAmount;
    }

    function _totalRepayable(
        uint256 principal,
        uint256 aprBps,
        uint256 durationMonths
    ) internal pure returns (uint256) {
        uint256 interest = (principal * aprBps * durationMonths) / (12 * BPS_DENOMINATOR);
        return principal + interest;
    }

    function _ceilDiv(uint256 a, uint256 b) internal pure returns (uint256) {
        return a == 0 ? 0 : ((a - 1) / b) + 1;
    }

    function _sendValue(address to, uint256 amount) internal {
        (bool success, ) = payable(to).call{value: amount}("");
        if (!success) revert TransferFailed();
    }
}

contracts/ReputationEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./VeilSBT.sol";

contract ReputationEngine is Ownable {
    VeilSBT public immutable veilSBT;
    address public loanMarketplace;

    int256 public constant ON_TIME_EMI_POINTS = 15;
    int256 public constant EARLY_REPAY_POINTS = 25;
    int256 public constant LOAN_COMPLETE_POINTS = 50;
    int256 public constant LATE_PAYMENT_POINTS = -20;
    int256 public constant DEFAULT_POINTS = -75;

    event LoanMarketplaceUpdated(address indexed loanMarketplace);
    event ReputationChange(
        address indexed borrower,
        int256 delta,
        uint256 oldScore,
        uint256 newScore,
        string newTier,
        string reason
    );

    error NotLoanMarketplace();

    modifier onlyLoanMarketplace() {
        if (msg.sender != loanMarketplace) revert NotLoanMarketplace();
        _;
    }

    constructor(address veilSBTAddress) Ownable(msg.sender) {
        veilSBT = VeilSBT(veilSBTAddress);
    }

    function setLoanMarketplace(address newLoanMarketplace) external onlyOwner {
        loanMarketplace = newLoanMarketplace;
        emit LoanMarketplaceUpdated(newLoanMarketplace);
    }

    function recordOnTimeEMI(address borrower) external onlyLoanMarketplace {
        _applyChange(borrower, ON_TIME_EMI_POINTS, "ON_TIME_EMI");
    }

    function recordEarlyRepay(address borrower) external onlyLoanMarketplace {
        _applyChange(borrower, EARLY_REPAY_POINTS, "EARLY_REPAY");
    }

    function recordLoanComplete(address borrower) external onlyLoanMarketplace {
        _applyChange(borrower, LOAN_COMPLETE_POINTS, "LOAN_COMPLETE");
    }

    function recordLatePayment(address borrower) external onlyLoanMarketplace {
        _applyChange(borrower, LATE_PAYMENT_POINTS, "LATE_PAYMENT");
    }

    function recordDefault(address borrower) external onlyLoanMarketplace {
        _applyChange(borrower, DEFAULT_POINTS, "DEFAULT");
    }

    function tierForScore(uint256 score) public pure returns (string memory) {
        if (score >= 8000) return "Platinum";
        if (score >= 6500) return "Gold";
        if (score >= 5000) return "Silver";
        return "Bronze";
    }

    function _applyChange(
        address borrower,
        int256 delta,
        string memory reason
    ) internal {
        VeilSBT.CreditData memory data = veilSBT.creditDataOf(borrower);
        uint256 oldScore = data.score;
        uint256 newScore;

        if (delta < 0) {
            uint256 decrease = uint256(-delta);
            newScore = decrease > oldScore ? 0 : oldScore - decrease;
        } else {
            newScore = oldScore + uint256(delta);
            if (newScore > 10000) newScore = 10000;
        }

        string memory newTier = tierForScore(newScore);
        veilSBT.updateReputation(borrower, newTier, newScore);

        emit ReputationChange(borrower, delta, oldScore, newScore, newTier, reason);
    }
}

contracts/VeilSBT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/utils/Base64.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

contract VeilSBT is ERC721, Ownable {
    using Strings for uint256;

    struct CreditData {
        string tier;
        uint256 score;
        bytes32 proofHash;
        uint256 timestamp;
    }

    error SoulBoundToken();
    error AlreadyMinted();
    error NotCreditOracle();
    error NotReputationEngine();
    error TokenNotFound();

    event Locked(uint256 tokenId);
    event CreditOracleUpdated(address indexed creditOracle);
    event ReputationEngineUpdated(address indexed reputationEngine);
    event ReputationUpdated(
        address indexed account,
        uint256 indexed tokenId,
        string tier,
        uint256 score
    );

    bytes4 private constant ERC5192_INTERFACE_ID = 0xb45a3c0e;

    uint256 private _nextTokenId = 1;

    address public creditOracle;
    address public reputationEngine;

    mapping(address => uint256) private _tokenOfOwner;
    mapping(uint256 => CreditData) private _creditData;

    modifier onlyCreditOracle() {
        if (msg.sender != creditOracle) revert NotCreditOracle();
        _;
    }

    modifier onlyReputationEngine() {
        if (msg.sender != reputationEngine) revert NotReputationEngine();
        _;
    }

    constructor() ERC721("VeilFi Credit Soul", "VEILSBT") Ownable(msg.sender) {}

    function setCreditOracle(address newCreditOracle) external onlyOwner {
        creditOracle = newCreditOracle;
        emit CreditOracleUpdated(newCreditOracle);
    }

    function setReputationEngine(address newReputationEngine) external onlyOwner {
        reputationEngine = newReputationEngine;
        emit ReputationEngineUpdated(newReputationEngine);
    }

    function mint(
        address to,
        string calldata tier,
        uint256 score,
        bytes32 proofHash
    ) external onlyCreditOracle returns (uint256 tokenId) {
        if (_tokenOfOwner[to] != 0) revert AlreadyMinted();

        tokenId = _nextTokenId++;
        _creditData[tokenId] = CreditData({
            tier: tier,
            score: score,
            proofHash: proofHash,
            timestamp: block.timestamp
        });
        _tokenOfOwner[to] = tokenId;

        _safeMint(to, tokenId);
        emit Locked(tokenId);
    }

    function updateReputation(
        address account,
        string calldata tier,
        uint256 score
    ) external onlyReputationEngine {
        uint256 tokenId = _tokenOfOwner[account];
        if (tokenId == 0) revert TokenNotFound();

        CreditData storage data = _creditData[tokenId];
        data.tier = tier;
        data.score = score;
        data.timestamp = block.timestamp;

        emit ReputationUpdated(account, tokenId, tier, score);
    }

    function tokenOfOwner(address account) external view returns (uint256) {
        return _tokenOfOwner[account];
    }

    function creditData(uint256 tokenId) external view returns (CreditData memory) {
        if (_ownerOf(tokenId) == address(0)) revert TokenNotFound();
        return _creditData[tokenId];
    }

    function creditDataOf(address account) external view returns (CreditData memory) {
        uint256 tokenId = _tokenOfOwner[account];
        if (tokenId == 0) revert TokenNotFound();
        return _creditData[tokenId];
    }

    function locked(uint256 tokenId) external view returns (bool) {
        if (_ownerOf(tokenId) == address(0)) revert TokenNotFound();
        return true;
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        if (_ownerOf(tokenId) == address(0)) revert TokenNotFound();

        CreditData memory data = _creditData[tokenId];
        string memory color = tierColor(data.tier);
        string memory svg = string.concat(
            '<svg xmlns="http://www.w3.org/2000/svg" width="720" height="720" viewBox="0 0 720 720">',
            '<rect width="720" height="720" fill="#020617"/>',
            '<circle cx="610" cy="110" r="180" fill="',
            color,
            '" opacity="0.28"/>',
            '<circle cx="120" cy="620" r="160" fill="#14B8A6" opacity="0.18"/>',
            '<rect x="54" y="54" width="612" height="612" rx="28" fill="#0F172A" stroke="',
            color,
            '" stroke-width="4"/>',
            '<text x="86" y="140" fill="#E2E8F0" font-family="Inter,Arial" font-size="34" font-weight="700">VeilFi Credit Soul</text>',
            '<text x="86" y="230" fill="',
            color,
            '" font-family="Inter,Arial" font-size="62" font-weight="800">',
            data.tier,
            "</text>",
            '<text x="86" y="315" fill="#CBD5E1" font-family="Inter,Arial" font-size="30">Score</text>',
            '<text x="86" y="382" fill="#FFFFFF" font-family="Inter,Arial" font-size="72" font-weight="800">',
            data.score.toString(),
            "</text>",
            '<text x="86" y="466" fill="#94A3B8" font-family="Inter,Arial" font-size="22">Proof</text>',
            '<text x="86" y="504" fill="#E2E8F0" font-family="monospace" font-size="18">',
            _shortProof(data.proofHash),
            "</text>",
            '<text x="86" y="580" fill="#94A3B8" font-family="Inter,Arial" font-size="22">Updated ',
            data.timestamp.toString(),
            "</text>",
            "</svg>"
        );

        string memory metadata = string.concat(
            '{"name":"VeilFi Credit Soul #',
            tokenId.toString(),
            '","description":"Non-transferable VeilFi credit reputation token.","image":"data:image/svg+xml;base64,',
            Base64.encode(bytes(svg)),
            '","attributes":[{"trait_type":"Tier","value":"',
            data.tier,
            '"},{"trait_type":"Score","value":',
            data.score.toString(),
            '},{"trait_type":"Proof Hash","value":"',
            Strings.toHexString(uint256(data.proofHash), 32),
            '"},{"trait_type":"Locked","value":"true"}]}'
        );

        return string.concat("data:application/json;base64,", Base64.encode(bytes(metadata)));
    }

    function tierColor(string memory tier) public pure returns (string memory) {
        bytes32 tierHash = keccak256(bytes(tier));

        if (tierHash == keccak256(bytes("Platinum"))) return "#6366F1";
        if (tierHash == keccak256(bytes("Gold"))) return "#F59E0B";
        if (tierHash == keccak256(bytes("Silver"))) return "#94A3B8";
        if (tierHash == keccak256(bytes("Bronze"))) return "#B45309";

        return "#64748B";
    }

    function supportsInterface(bytes4 interfaceId) public view override returns (bool) {
        return interfaceId == ERC5192_INTERFACE_ID || super.supportsInterface(interfaceId);
    }

    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override returns (address from) {
        from = super._update(to, tokenId, auth);
        if (from != address(0) && to != address(0)) revert SoulBoundToken();
    }

    function _shortProof(bytes32 proofHash) private pure returns (string memory) {
        bytes memory full = bytes(Strings.toHexString(uint256(proofHash), 32));
        bytes memory shortened = new bytes(23);

        for (uint256 i = 0; i < 12; i++) {
            shortened[i] = full[i];
        }

        shortened[12] = ".";
        shortened[13] = ".";
        shortened[14] = ".";

        for (uint256 i = 0; i < 8; i++) {
            shortened[15 + i] = full[full.length - 8 + i];
        }

        return string(shortened);
    }
}

